[{"order":1,"type":"heading","text":"Spring Security: Authentication and Authorization in Spring Boot"},{"order":2,"type":"paragraph","text":"Spring Security is a powerful and highly customizable authentication and access-control framework. It provides comprehensive security services for Java applications. In this tutorial, we'll explore how to use Spring Security with Spring Boot to secure your application."},{"order":3,"type":"heading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Java Development Kit (JDK) 8 or higher"},{"order":5,"type":"bullet_point","text":"Maven or Gradle"},{"order":6,"type":"bullet_point","text":"An IDE (e.g., IntelliJ IDEA, Eclipse, VS Code)"},{"order":7,"type":"bullet_point","text":"Basic understanding of Spring Boot"},{"order":8,"type":"heading","text":"Setting up a Spring Boot Project"},{"order":9,"type":"paragraph","text":"Let's start by creating a new Spring Boot project. You can use Spring Initializr (https://start.spring.io/) to generate a basic project structure."},{"order":10,"type":"paragraph","text":"Configure the following dependencies:"},{"order":11,"type":"bullet_point","text":"Spring Web"},{"order":12,"type":"bullet_point","text":"Spring Security"},{"order":13,"type":"bullet_point","text":"Thymeleaf (optional, for view rendering)"},{"order":14,"type":"paragraph","text":"Once you have configured the dependencies, download the project and import it into your IDE."},{"order":15,"type":"heading","text":"Adding Spring Security Configuration"},{"order":16,"type":"paragraph","text":"Create a new class named `SecurityConfig` and annotate it with `@Configuration` and `@EnableWebSecurity`. This class will be responsible for configuring Spring Security."},{"order":17,"type":"code","text":"@Configuration
@EnableWebSecurity
public class SecurityConfig extends WebSecurityConfigurerAdapter {

    @Override
    protected void configure(HttpSecurity http) throws Exception {
        http
            .authorizeRequests()
                .antMatchers("/", "/home").permitAll()
                .anyRequest().authenticated()
                .and()
            .formLogin()
                .loginPage("/login")
                .permitAll()
                .and()
            .logout()
                .permitAll();
    }

    @Bean
    @Override
    public UserDetailsService userDetailsService() {
        UserDetails user = User.withDefaultPasswordEncoder()
                .username("user")
                .password("password")
                .roles("USER")
                .build();
        return new InMemoryUserDetailsManager(user);
    }
}"},{"order":18,"type":"paragraph","text":"Explanation:"},{"order":19,"type":"bullet_point","text":"`@Configuration`: Indicates that this class provides Spring configuration."},{"order":20,"type":"bullet_point","text":"`@EnableWebSecurity`: Enables Spring Security's web security support."},{"order":21,"type":"bullet_point","text":"`WebSecurityConfigurerAdapter`: Provides default security configurations."},{"order":22,"type":"bullet_point","text":"`configure(HttpSecurity http)`: Configures the HTTP security settings."},{"order":23,"type":"bullet_point","text":"`authorizeRequests()`: Configures authorization rules."},{"order":24,"type":"bullet_point","text":"`antMatchers("/", "/home").permitAll()`: Allows unauthenticated access to the `/` and `/home` paths."},{"order":25,"type":"bullet_point","text":"`anyRequest().authenticated()`: Requires authentication for all other requests."},{"order":26,"type":"bullet_point","text":"`formLogin()`: Configures form-based login."},{"order":27,"type":"bullet_point","text":"`loginPage("/login")`: Specifies the login page URL."},{"order":28,"type":"bullet_point","text":"`logout()`: Configures logout functionality."},{"order":29,"type":"bullet_point","text":"`userDetailsService()`: Defines a user details service. In this example, we are using an in-memory user store."},{"order":30,"type":"heading","text":"Creating a Login Page"},{"order":31,"type":"paragraph","text":"Create a simple HTML page for the login form. If you are using Thymeleaf, create a `login.html` file in the `src/main/resources/templates` directory."},{"order":32,"type":"code","text":"<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:th="http://www.thymeleaf.org"
      xmlns:sec="http://www.thymeleaf.org/thymeleaf-extras-springsecurity3">
<head>
    <title>Spring Security Login</title>
</head>
<body>
<div th:if="${param.error}">
    Invalid username and password.
</div>
<div th:if="${param.logout}">
    You have been logged out.
</div>
<form th:action="@{/login}" method="post">
    <div><label> User Name : <input type="text" name="username"/> </label></div>
    <div><label> Password: <input type="password" name="password"/> </label></div>
    <div><input type="submit" value="Sign In"/></div>
</form>
</body>
</html>"},{"order":33,"type":"paragraph","text":"This HTML creates a basic login form with fields for username and password. The form submits to the `/login` URL, which is handled by Spring Security."},{"order":34,"type":"heading","text":"Creating a Controller"},{"order":35,"type":"paragraph","text":"Create a simple controller to handle the `/` and `/home` requests."},{"order":36,"type":"code","text":"@Controller
public class HomeController {

    @GetMapping("/")
    public String index() {
        return "index";
    }

    @GetMapping("/home")
    public String home() {
        return "home";
    }

    @GetMapping("/login")
    public String login() {
        return "login";
    }

    @GetMapping("/hello")
    public String hello(Model model) {
        model.addAttribute("message", "Hello, Secured World!");
        return "hello";
    }
}"},{"order":37,"type":"paragraph","text":"Create corresponding Thymeleaf templates `index.html`, `home.html`, and `hello.html` in the `src/main/resources/templates` directory."},{"order":38,"type":"code","text":"<!DOCTYPE html>
<html xmlns:th="http://www.thymeleaf.org">
<head>
    <title>Index</title>
</head>
<body>
<h1>Welcome to the Index Page!</h1>
<p><a th:href="@{/home}">Go to Home</a></p>
</body>
</html>"},{"order":39,"type":"code","text":"<!DOCTYPE html>
<html xmlns:th="http://www.thymeleaf.org">
<head>
    <title>Home</title>
</head>
<body>
<h1>Welcome to the Home Page!</h1>
<p>This page is accessible to everyone.</p>
<p><a th:href="@{/hello}">Go to Hello (Requires Authentication)</a></p>
</body>
</html>"},{"order":40,"type":"code","text":"<!DOCTYPE html>
<html xmlns:th="http://www.thymeleaf.org">
<head>
    <title>Hello</title>
</head>
<body>
<h1 th:text="${message}"></h1>
<form th:action="@{/logout}" method="post">
    <input type="submit" value="Sign Out"/>
</form>
</body>
</html>"},{"order":41,"type":"heading","text":"Running the Application"},{"order":42,"type":"paragraph","text":"Run the Spring Boot application. Access `/` or `/home` in your browser; these pages should be accessible without authentication. Access `/hello`; you will be redirected to the login page. Use the username `user` and password `password` to log in."},{"order":43,"type":"heading","text":"Adding Role-Based Authorization"},{"order":44,"type":"paragraph","text":"To implement role-based authorization, modify the `SecurityConfig` class."},{"order":45,"type":"code","text":"@Configuration
@EnableWebSecurity
public class SecurityConfig extends WebSecurityConfigurerAdapter {

    @Override
    protected void configure(HttpSecurity http) throws Exception {
        http
            .authorizeRequests()
                .antMatchers("/", "/home").permitAll()
                .antMatchers("/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated()
                .and()
            .formLogin()
                .loginPage("/login")
                .permitAll()
                .and()
            .logout()
                .permitAll();
    }

    @Bean
    @Override
    public UserDetailsService userDetailsService() {
        UserDetails user = User.withDefaultPasswordEncoder()
                .username("user")
                .password("password")
                .roles("USER")
                .build();

        UserDetails admin = User.withDefaultPasswordEncoder()
                .username("admin")
                .password("admin")
                .roles("ADMIN")
                .build();

        return new InMemoryUserDetailsManager(user, admin);
    }
}"},{"order":46,"type":"paragraph","text":"Explanation:"},{"order":47,"type":"bullet_point","text":"`.antMatchers("/admin/**").hasRole("ADMIN")`: Requires the `ADMIN` role to access any URL starting with `/admin/`."},{"order":48,"type":"bullet_point","text":"We added a new user with the `ADMIN` role."},{"order":49,"type":"paragraph","text":"Create an `/admin` endpoint and a corresponding view."},{"order":50,"type":"code","text":"@Controller
public class AdminController {

    @GetMapping("/admin")
    public String adminPage() {
        return "admin";
    }
}"},{"order":51,"type":"code","text":"<!DOCTYPE html>
<html xmlns:th="http://www.thymeleaf.org">
<head>
    <title>Admin</title>
</head>
<body>
<h1>Welcome to the Admin Page!</h1>
</body>
</html>"},{"order":52,"type":"paragraph","text":"Now, only users with the `ADMIN` role (like the `admin` user) can access the `/admin` page."},{"order":53,"type":"heading","text":"Using a Database for User Details"},{"order":54,"type":"paragraph","text":"Using an in-memory user store is not suitable for production. Let's configure Spring Security to use a database for storing user details. First, add the necessary dependencies to your `pom.xml` or `build.gradle`."},{"order":55,"type":"bullet_point","text":"Spring Data JPA"},{"order":56,"type":"bullet_point","text":"A database driver (e.g., H2, MySQL, PostgreSQL)"},{"order":57,"type":"paragraph","text":"Example using H2 database:"},{"order":58,"type":"code","text":"<dependency>
    <groupId>org.springframework.boot</groupId>
    <artifactId>spring-boot-starter-data-jpa</artifactId>
</dependency>
<dependency>
    <groupId>com.h2database</groupId>
    <artifactId>h2</artifactId>
    <scope>runtime</scope>
</dependency>"},{"order":59,"type":"paragraph","text":"Create a `User` entity:"},{"order":60,"type":"code","text":"@Entity
@Table(name = "users")
public class User {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false, unique = true)
    private String username;

    @Column(nullable = false)
    private String password;

    private boolean enabled;

    @ManyToMany(fetch = FetchType.EAGER)
    @JoinTable(
            name = "users_roles",
            joinColumns = @JoinColumn(
                    name = "user_id", referencedColumnName = "id"),
            inverseJoinColumns = @JoinColumn(
                    name = "role_id", referencedColumnName = "id"))
    private Collection<Role> roles;

    // Getters and setters

    public User() {
    }

    public User(String username, String password, boolean enabled, Collection<Role> roles) {
        this.username = username;
        this.password = password;
        this.enabled = enabled;
        this.roles = roles;
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getUsername() {
        return username;
    }

    public void setUsername(String username) {
        this.username = username;
    }

    public String getPassword() {
        return password;
    }

    public void setPassword(String password) {
        this.password = password;
    }

    public boolean isEnabled() {
        return enabled;
    }

    public void setEnabled(boolean enabled) {
        this.enabled = enabled;
    }

    public Collection<Role> getRoles() {
        return roles;
    }

    public void setRoles(Collection<Role> roles) {
        this.roles = roles;
    }
}"},{"order":61,"type":"paragraph","text":"Create a `Role` entity:"},{"order":62,"type":"code","text":"@Entity
@Table(name = "roles")
public class Role {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false, unique = true)
    private String name;

    public Role() {
    }

    public Role(String name) {
        this.name = name;
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }
}"},{"order":63,"type":"paragraph","text":"Create a `UserRepository` interface:"},{"order":64,"type":"code","text":"public interface UserRepository extends JpaRepository<User, Long> {
    User findByUsername(String username);
}"},{"order":65,"type":"paragraph","text":"Create a `RoleRepository` interface:"},{"order":66,"type":"code","text":"public interface RoleRepository extends JpaRepository<Role, Long> {
    Role findByName(String name);
}"},{"order":67,"type":"paragraph","text":"Create a custom `UserDetailsService`:"},{"order":68,"type":"code","text":"@Service
public class CustomUserDetailsService implements UserDetailsService {

    @Autowired
    private UserRepository userRepository;

    @Override
    public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {
        User user = userRepository.findByUsername(username);
        if (user == null) {
            throw new UsernameNotFoundException("User not found with username: " + username);
        }
        return new org.springframework.security.core.userdetails.User(
                user.getUsername(), user.getPassword(), mapRolesToAuthorities(user.getRoles()));
    }

    private Collection<? extends GrantedAuthority> mapRolesToAuthorities(Collection<Role> roles) {
        return roles.stream().map(role -> new SimpleGrantedAuthority(role.getName())).collect(Collectors.toList());
    }
}"},{"order":69,"type":"paragraph","text":"Update the `SecurityConfig` to use the custom `UserDetailsService`:"},{"order":70,"type":"code","text":"@Configuration
@EnableWebSecurity
public class SecurityConfig extends WebSecurityConfigurerAdapter {

    @Autowired
    private CustomUserDetailsService userDetailsService;

    @Bean
    public BCryptPasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Override
    protected void configure(AuthenticationManagerBuilder auth) throws Exception {
        auth.userDetailsService(userDetailsService).passwordEncoder(passwordEncoder());
    }

    @Override
    protected void configure(HttpSecurity http) throws Exception {
        http
            .authorizeRequests()
                .antMatchers("/", "/home", "/registration").permitAll()
                .antMatchers("/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated()
                .and()
            .formLogin()
                .loginPage("/login")
                .permitAll()
                .and()
            .logout()
                .permitAll();
    }
}"},{"order":71,"type":"paragraph","text":"Explanation:"},{"order":72,"type":"bullet_point","text":"We autowired the `CustomUserDetailsService`."},{"order":73,"type":"bullet_point","text":"We added a `BCryptPasswordEncoder` bean to encrypt passwords."},{"order":74,"type":"bullet_point","text":"In the `configure(AuthenticationManagerBuilder auth)` method, we configured the `AuthenticationManagerBuilder` to use our custom `UserDetailsService` and the `BCryptPasswordEncoder`."},{"order":75,"type":"paragraph","text":"Create a registration endpoint and service to add new users to the database. Remember to encode the password before saving it to the database."},{"order":76,"type":"heading","text":"Conclusion"},{"order":77,"type":"paragraph","text":"This tutorial covered the basics of Spring Security with Spring Boot, including authentication, authorization, role-based access control, and using a database for user details. Spring Security is highly customizable, and you can further explore its features to meet your specific application requirements."}]
